 const chooseSeq=useRef(0);
 async function preselectRecommended(p:CheckoutPerson,seq:number){try{const r=await checkoutRecommended(token,p.enrollment_id);if(seq!==chooseSeq.current||!r?.ready||!r.allocations?.length)return;
   setSelected(prev=>prev.length?prev:r.allocations.map(a=>a.charge_id));setAmount(prev=>prev||String(r.total))}catch{/* no recommendation: the cashier picks */}}
 async function choose(p:CheckoutPerson){const seq=++chooseSeq.current;setActive(p);setQ('');setHits([]);setSelected([]);setAmount('');setMsg('');setLastPay(null);setBasketDone(null);try{setCharges((await checkoutBalance(token,p.enrollment_id)).items);void preselectRecommended(p,seq);const required=await checkoutRegistrationBundle(token,p.enrollment_id).catch(()=>null);if(required)setRequiredByEnrollment(rows=>({...rows,[p.enrollment_id]:required}));if(can('finance.old_debt.read'))setOldDebts((await checkoutOldDebts(token,p.student_id)).items)}catch(e){setMsg(friendlyError(e))}}
 async function addFamily(){if(!active)return;try{const x=await checkoutFamily(token,active.family_id);setCart(old=>[...old,...x.items.filter(n=>!old.some(o=>o.student_id===n.student_id))]);const pairs=await Promise.all(x.items.map(async child=>[child.enrollment_id,await checkoutRegistrationBundle(token,child.enrollment_id).catch(()=>null)] as const));setRequiredByEnrollment(rows=>({...rows,...Object.fromEntries(pairs.filter((pair):pair is readonly [string,RegistrationBundleDue]=>pair[1]!==null))}))}catch(e){setMsg(friendlyError(e))}}
 const [payOptions,setPayOptions]=useState<PaymentOptions|null>(null);const [payMode,setPayMode]=useState('CASH');const [payRef,setPayRef]=useState('');
 const chosen=charges.filter(c=>selected.includes(c.id));const currencies=[...new Set(chosen.map(c=>c.currency))];const total=chosen.reduce((a,c)=>a+Number(c.remaining),0);const entered=Number(amount||total);const fundAllowed=can('finance.advance_funds.receive')&&payOptions?.advance_payments_enabled===true;const valid=selected.length>0&&currencies.length===1&&entered>0&&(entered<=total||fundAllowed);
 const selectable=(c:CheckoutCharge,sel:string[]=selected)=>c.eligible||((c.requires?.length??0)>0&&(c.requires??[]).every(r=>sel.includes(r)));function toggle(c:CheckoutCharge){if(!selectable(c)&&!selected.includes(c.id))return;setSelected(prev=>{let next=prev.includes(c.id)?prev.filter(x=>x!==c.id):[...prev,c.id];if(prev.includes(c.id))next=next.filter(id=>!(charges.find(x=>x.id===id)?.requires??[]).includes(c.id));const due=charges.filter(x=>next.includes(x.id)).reduce((a,x)=>a+Number(x.remaining),0);setAmount(String(due||''));return next})}
 async function nextMonth(){if(!active)return;try{const r=await checkoutRecommended(token,active.enrollment_id);if(!r.ready){setMsg(r.reason||'Aucune action conseillée');return}const ids=r.allocations.map(a=>a.charge_id);setSelected(ids);setAmount(r.total);setMsg(`Action conseillée : ${r.label} · ${money(r.total,r.currency||'CDF')}`)}catch(e){setMsg(friendlyError(e))}}const [bundle,setBundle]=useState<{ready:boolean;items:{id:string}[];totals:Record<string,string>}|null>(null);useEffect(()=>{setBundle(null);if(active)checkoutFeeBundle(token,active.enrollment_id).then(setBundle).catch(()=>setBundle(null))},[active?.enrollment_id,charges.length]);function selectBundle(){if(!bundle)return;const ids=bundle.items.map(i=>i.id);setSelected(ids);setAmount(String(charges.filter(c=>ids.includes(c.id)).reduce((a,c)=>a+Number(c.remaining),0)))}

